param([string]$SavePath=(Join-Path $PSScriptRoot '../../.local-research/runtime/profile-20261102/Saves/plants-stopped-b.rws'))
# Read-only XML extraction; no target assembly execution or compressed-map decoding.
$ErrorActionPreference='Stop'
$s=[xml](Get-Content -Raw -LiteralPath $SavePath)
$keys=@($s.SelectNodes('//researchManager/progress/keys/li'));$vals=@($s.SelectNodes('//researchManager/progress/values/li'));$treeResearch=$null
for($i=0;$i -lt $keys.Count;$i++){if($keys[$i].InnerText -eq 'TreeSowing'){$treeResearch=[double]::Parse($vals[$i].InnerText,[Globalization.CultureInfo]::InvariantCulture)}}
$zones=@($s.SelectNodes('//zoneManager/allZones/li[@Class="Zone_Growing"]')|ForEach-Object{[ordered]@{id=[int]$_.ID;label=[string]$_.label;cells=@($_.SelectNodes('cells/li')|ForEach-Object{$_.InnerText});plant=[string]$_.plantDefToGrow;hidden=([string]$_.hidden -eq 'True')}})
$cacti=@($s.SelectNodes('//thing[def="Plant_SaguaroCactus" and (id="Plant_SaguaroCactus38625" or id="Plant_SaguaroCactus39903")]')|ForEach-Object{[ordered]@{id=[string]$_.id;def=[string]$_.def;pos=[string]$_.pos;health=[int]$_.health;growth=[double]::Parse($_.growth,[Globalization.CultureInfo]::InvariantCulture);age=[int]$_.age}}|Sort-Object {$_.id})
$wood=@($s.SelectNodes('//thing[def="WoodLog"]')|ForEach-Object{[ordered]@{id=[string]$_.id;pos=[string]$_.pos;count=if($_.SelectSingleNode('stackCount')){[int]$_.stackCount}else{1}}}|Sort-Object {$_.id})
$pawns=@($s.SelectNodes('//thing[def="Human"]')|ForEach-Object{[ordered]@{id=[string]$_.id;nick=[string]$_.name.nick;job=[string]$_.jobs.curJob.def;plants_skill=[int]$_.SelectSingleNode('skills/skills/li[def="Plants"]').level}}|Sort-Object {$_.id})
[ordered]@{file=(Split-Path -Leaf $SavePath);sha256=(Get-FileHash -LiteralPath $SavePath -Algorithm SHA256).Hash.ToLowerInvariant();bytes=(Get-Item -LiteralPath $SavePath).Length;version=$s.SelectSingleNode('//meta/gameVersion').InnerText;mods=@($s.SelectNodes('//meta/modIds/li')|ForEach-Object{$_.InnerText});tick=[int]$s.SelectSingleNode('//tickManager/ticksGame').InnerText;tree_sowing_research_progress=$treeResearch;growing_zones=$zones;recorded_cacti=$cacti;explicit_wood=$wood;pawns=$pawns;designations=@($s.SelectNodes('//designationManager/allDesignations/li')|ForEach-Object{[ordered]@{def=[string]$_.def;target=[string]$_.target}});scope='Explicit save XML only. Research progress is a stored value, not a runtime disabled-reason test; no harvest was executed.'}|ConvertTo-Json -Depth 14
